function tab(name){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===name));$('crumb').textContent={planner:'Pallet planner',chat:'Chat assistant',catalogue:'Product catalogue',saved:'Saved plans'}[name];if(name==='catalogue')renderCatalogue();if(name==='saved')renderSaved();}
