function currentModel(){return products.find(p=>p.model.toUpperCase()===$('model').value.trim().toUpperCase())}
function ready(p){return p.dims?.length===3&&p.dims.every(v=>Number.isFinite(v)&&v>0)&&Number.isFinite(p.weight)&&p.weight>0}
function updateModel(){let p=currentModel();$('modelinfo').innerHTML=p?`${esc(p.name)}<br>${ready(p)?`Carton ${p.dims.join(' × ')} mm (W × D × H) · ${p.weight} kg gross`:'Shipping data incomplete · update in catalogue'} · ${p.userSupplied?'User supplied':`<a target="_blank" rel="noopener" href="${esc(p.url)}">LG source ↗</a>`}`:'Select an exact model from the catalogue.';updateLayerPreview();}
