 $('dimensionrows').innerHTML=rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.value)}</td></tr>`).join('')||'<tr><td colspan="2">LG specifications are unavailable for this listing. Add verified shipping data using Edit.</td></tr>';
