const safeSourceUrl=url=>typeof url==='string'&&/^https:\/\//i.test(url)?url:'#';
async function showProductDetails(product){
 selectedDetailProduct=product;$('productdetailstitle').textContent=product.model+' · Full model details';$('productdetailsrows').innerHTML='<tr><td colspan="2">Loading published specifications…</td></tr>';$('productdetailsmetadata').textContent='';$('productdetailssource').replaceChildren();$('specsearch').value='';$('productdetailsdocuments').replaceChildren();$('productdetailsshipping').textContent='Planner shipping inputs: '+(product.dims?'W × D × H '+product.dims.join(' × ')+' mm':'carton dimensions missing')+' · '+(product.weight?product.weight+' kg gross':'gross weight missing')+(product.userSupplied?' · User supplied':'')+(product.sourceDifferences?' · Sources report different packing data; check the selected market.':'');$('productdetailsdialog').showModal();
 try{const all=await fullDetails();if(selectedDetailProduct!==product)return;const entry=all[product.model];detailSources=[...(entry?.primary?[entry.primary]:[]),...(entry?.sources||[])].filter(s=>s.status==='verified');
  if(!detailSources.length){$('productdetailsrows').innerHTML='<tr><td colspan="2">No verified product specifications were found for this exact model. Check the model code and carton label.</td></tr>';return;}
  detailSources=detailSources.filter((s,i,a)=>a.findIndex(t=>t.url===s.url)===i);const sourceScore=s=>(s.fullSpecs?.length?100000:0)+(s.bundle?-200000:0)+(['sa_en','sa_ar'].includes(s.market)?10000:0)+(s.url===product.url?1000:0)+(s.fullSpecs?.length||0);detailSources.sort((a,b)=>sourceScore(b)-sourceScore(a));
  $('productdetailssource').innerHTML=detailSources.map((s,i)=>`<option value="${i}">${esc(marketNames[s.market]||s.market)}${s.retailer?' · '+esc(s.retailer):''} · ${esc(s.modelCode||product.model)} · ${s.fullSpecs?.length||0} specs</option>`).join('');renderProductDetails();
 }catch(error){$('productdetailsrows').innerHTML=`<tr><td colspan="2">${esc(error.message)}</td></tr>`;}
}
function renderProductDetails(){const source=detailSources[Number($('productdetailssource').value)||0];if(!source)return;const q=$('specsearch').value.trim().toLowerCase(),rows=(source.fullSpecs||[]).filter(r=>(r.label+' '+r.value).toLowerCase().includes(q));$('productdetailsmetadata').innerHTML=`<a href="${esc(safeSourceUrl(source.url))}" target="_blank" rel="noopener">Open source ↗</a> · ${esc(marketNames[source.market]||source.market)}${source.retailer?' · '+esc(source.retailer)+' (retailer reference)':' · Official LG'} · Model ${esc(source.modelCode)} · Checked ${esc(source.checked)}${!['sa_en','sa_ar'].includes(source.market)?'<br><b>Regional reference: verify your actual Saudi carton before using these shipping measurements.</b>':''}`;$('productdetailsrows').innerHTML=rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.value)}</td></tr>`).join('')||'<tr><td colspan="2">No matching published specifications.</td></tr>';$('productdetailsdocuments').innerHTML=(source.documents||[]).length?'<h3>Source documents</h3>'+source.documents.map((url,i)=>`<p><a class="textbtn" href="${esc(safeSourceUrl(url))}" target="_blank" rel="noopener">LG document ${i+1} ↗</a></p>`).join(''):'';if(source.supportUrl)$('productdetailsdocuments').innerHTML+=`<p><a class="textbtn" href="${esc(safeSourceUrl(source.supportUrl))}" target="_blank" rel="noopener">LG support & manuals ↗</a></p>`;}
$('closeproductdetails').onclick=()=>$('productdetailsdialog').close();$('productdetailssource').onchange=renderProductDetails;$('specsearch').oninput=renderProductDetails;
